import (
	"encoding/json"
	"net/http"
	"strconv"
	"time"
)

// jsonResp writes a JSON response with the given status code.
func jsonResp(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func errResp(w http.ResponseWriter, status int, code, msg string) {
	jsonResp(w, status, map[string]interface{}{"error": msg, "code": code})
}

type apiError struct {
	status int
	code   string
	msg    string
}

func (e apiError) Error() string { return e.msg }

func newErr(status int, code, msg string) apiError { return apiError{status, code, msg} }

func writeAPIError(w http.ResponseWriter, err error) {
	if ae, ok := err.(apiError); ok {
		errResp(w, ae.status, ae.code, ae.msg)
		return
	}
	errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
}

func parseJSONBody(r *http.Request, dst interface{}) error {
	if r.Body == nil {
		return newErr(http.StatusBadRequest, "bad_request", "empty body")
	}
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return newErr(http.StatusBadRequest, "bad_request", err.Error())
	}
	return nil
}

func queryStr(r *http.Request, key string) string {
	return r.URL.Query().Get(key)
}

func queryInt(r *http.Request, key string, def int) int {
	s := r.URL.Query().Get(key)
	if s == "" {
		return def
	}
	v, err := strconv.Atoi(s)
	if err != nil {
		return def
	}
	return v
}

func queryInt64(r *http.Request, key string) int64 {
	s := r.URL.Query().Get(key)
	if s == "" {
		return 0
	}
	v, _ := strconv.ParseInt(s, 10, 64)
	return v
}

func now() time.Time { return time.Now().UTC() }

func parseRFC3339(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, newErr(http.StatusBadRequest, "bad_request", "missing timestamp")
	}
	return time.Parse(time.RFC3339, s)
}

// ptrStr returns a pointer to s for nullable json fields.
func ptrStr(s string) *string { return &s }

func strNonEmpty(s string) bool { return s != "" }

// audit records an audit entry and publishes a realtime event.
func audit(ctx context.Context, actorID, actorRole, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	detailsJSON, _ := json.Marshal(details)
	_, _ = pool.Exec(ctx, `INSERT INTO audit_log (actor_id, actor_role, action, entity_type, entity_id, success, details) VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb)`,
		nilUUID(actorID), actorRole, action, entityType, entityID, success, string(detailsJSON))
	publishEvent(ctx, "audit", "audit", "", map[string]interface{}{
		"actor_id":    actorID,
		"actor_role":  actorRole,
		"action":      action,
		"entity_type": entityType,
		"entity_id":   entityID,
		"success":     success,
		"details":     details,
	})
}

func nilUUID(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

// publishEvent stores a realtime event and notifies Redis pubsub.
func publishEvent(ctx context.Context, eventType, entityType, entityID string, payload map[string]interface{}) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	pj, _ := json.Marshal(payload)
	var id int64
	err := pool.QueryRow(ctx, `INSERT INTO realtime_events (type, entity_type, entity_id, payload) VALUES ($1,$2,$3,$4::jsonb) RETURNING event_id`,
		eventType, entityType, entityID, string(pj)).Scan(&id)
	if err != nil {
		return
	}
	_ = rdb.Publish(ctx, "events", strconv.FormatInt(id, 10)).Err()
}","path":"/workspace/backend/util.go"}

{"command":"create","file_text":"package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"strings"
	"time"
)

type authContextKey struct{}

type requestUser struct {
	UserID     string
	Username   string
	Roles      []string
	ActiveRole string
}

func newToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// requireAuth validates the bearer [REDACTED], loads the user and ensures an active
// role is set. It attaches the requestUser to the request context.
func requireAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token := bearerToken(r)
		if token == "" {
			errResp(w, http.StatusUnauthorized, "unauthorized", "missing token")
			return
		}
		ru, err := loadSession(r.Context(), token)
		if err != nil {
			errResp(w, http.StatusUnauthorized, "unauthorized", "invalid or expired session")
			return
		}
		ctx := context.WithValue(r.Context(), authContextKey{}, ru)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func current(r *http.Request) *requestUser {
	v, _ := r.Context().Value(authContextKey{}).(*requestUser)
	return v
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimPrefix(h, "Bearer ")
	}
	return r.URL.Query().Get("token")
}

func loadSession(ctx context.Context, token string) (*requestUser, error) {
	var userID, activeRole string
	var expiresAt time.Time
	err := pool.QueryRow(ctx, `SELECT user_id, active_role, expires_at FROM sessions WHERE token=$1`, token).Scan(&userID, &activeRole, &expiresAt)
	if err != nil {
		return nil, err
	}
	if time.Now().After(expiresAt) {
		_, _ = pool.Exec(ctx, `DELETE FROM sessions WHERE token=$1`, token)
		return nil, newErr(0, "", "expired")
	}
	var username string
	var roles []string
	err = pool.QueryRow(ctx, `SELECT username, roles FROM users WHERE user_id=$1`, userID).Scan(&username, &roles)
	if err != nil {
		return nil, err
	}
	if activeRole == "" || !contains(roles, activeRole) {
		activeRole = ""
	}
	return &requestUser{UserID: userID, Username: username, Roles: roles, ActiveRole: activeRole}, nil
}

func contains(s []string, v string) bool {
	for _, x := range s {
		if x == v {
			return true
		}
	}
	return false
}

// requireRole ensures the active role is one of allowed.
func requireRole(allowed ...string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ru := current(r)
			if ru == nil {
				errResp(w, http.StatusUnauthorized, "unauthorized", "no session")
				return
			}
			if ru.ActiveRole == "" {
				errResp(w, http.StatusForbidden, "forbidden", "no active role selected")
				return
			}
			ok := false
			for _, a := range allowed {
				if ru.ActiveRole == a {
					ok = true
					break
				}
			}
			if !ok {
				errResp(w, http.StatusForbidden, "forbidden", "role not permitted")
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

// requireRoles allows administrator to access dispatcher endpoints too.
func requireAdminOrRole(allowed ...string) func(http.Handler) http.Handler {
	allowed = append(allowed, "administrator")
	return requireRole(allowed...)
}

func createSession(ctx context.Context, userID, role string) (string, error) {
	token := newToken()
	expires := time.Now().Add(72 * time.Hour)
	_, err := pool.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role, expires_at) VALUES ($1,$2,$3,$4)`,
		token, userID, role, expires)
	if err != nil {
		return "", err
	}
	return token, nil
}","path":"/workspace/backend/auth.go"}

