            out.write(f"summary: {op['summary']}\n")
        if 'description' in op:
            out.write(f"desc: {op['description']}\n")
        for p in op.get('parameters', []):
            out.write(f"  param {p.get('in')} {p.get('name')} required={p.get('required')} schema={json.dumps(p.get('schema'))}\n")
        rb = op.get('requestBody', {})
        if rb:
            content = rb.get('content', {})
            app = content.get('application/json', {})
            sch = app.get('schema', {})
            out.write(f"  requestBody: {ref(sch)}\n")
        for code, resp in op.get('responses', {}).items():
            content = resp.get('content', {})
            app = content.get('application/json', {})
