func adminOnly(ru *requestUser) bool { return ru.ActiveRole == "administrator" }

func handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if !adminOnly(ru) {
		errResp(w, http.StatusForbidden, "forbidden", "administrator only")
