	if lat < -90 || lat > 90 || lng < -180 || lng > 180 {
		errResp(w, http.StatusBadRequest, "invalid_coordinate", "coordinate out of range")
		return
	}
	cov := 0.0
	if body.CoverageKm != nil {
		cov = *body.CoverageKm
	}
	if cov < 0 {
		errResp(w, http.StatusBadRequest, "invalid_node_coverage", "coverage must be >= 0")
