	handling := 0
	if body.HandlingMinutes != nil {
		handling = *body.HandlingMinutes
	}
	if handling < 0 {
		errResp(w, http.StatusBadRequest, "invalid_handling_time", "handling minutes must be >= 0")
		return
	}
