	if err != nil {
		errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	audit(r.Context(), ru.UserID, ru.ActiveRole, "create_location", "location", id, true, map[string]interface{}{"name": body.Name})
	emitEvent(r.Context(), "location", "location", id, map[string]interface{}{"locationId": id, "name": body.Name})
