func emitEvent(ctx context.Context, eventType, entityType, entityID string, payload map[string]interface{}) {
	publishEvent(ctx, eventType, entityType, entityID, payload)
}

// atoiSafe parses integer without error.
func atoiSafe(s string) int {
	v, _ := strconv.Atoi(s)
	return v
}

// staleThreshold: location considered stale after 30 minutes.
const staleThresholdMinutes = 30

func isStale(recordedAt string) bool {
	if recordedAt == "" {
		return true
	}
	t, err := parseRFC3339(recordedAt)
	if err != nil {
		return true
	}
	return now().Sub(t) > staleThresholdMinutes
