{"command":"create","file_text":"package main

import (
	"context"
	"encoding/json"
	"math"
	"sync/atomic"
	"time"
)

var netRevision int64 = 1

func bumpNetworkRevision() {
	atomic.AddInt64(&netRevision, 1)
}

func recomputeServiceabilityAsync(ctx context.Context) {
	bumpNetworkRevision()
	go func() {
		_ = recomputeServiceability(context.Background())
	}()
}

type locationNode struct {
	ID              string
	Name            string
	Lat, Lng        float64
	CoverageKm      float64
	HandlingMinutes int
	Active          bool
	CollectionPoint bool
	TransferPoint   bool
	Hub             bool
	Laboratory      bool
}

type connectionEdge struct {
	ID            string
	From, To      string
	TravelMinutes int
	Cost          float64
	Cooled        bool
	Active        bool
}

func loadNetwork(ctx context.Context) (map[string]*locationNode, []*connectionEdge, error) {
	nodes := map[string]*locationNode{}
	rows, err := pool.Query(ctx, `SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations`)
	if err != nil {
		return nil, nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var n locationNode
		if err := rows.Scan(&n.ID, &n.Name, &n.Lat, &n.Lng, &n.CoverageKm, &n.HandlingMinutes, &n.Active, &n.CollectionPoint, &n.TransferPoint, &n.Hub, &n.Laboratory); err != nil {
			return nil, nil, err
		}
		nodes[n.ID] = &n
	}
	conns := []*connectionEdge{}
	rows2, err := pool.Query(ctx, `SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
	if err != nil {
		return nil, nil, err
	}
	defer rows2.Close()
	for rows2.Next() {
		var c connectionEdge
		if err := rows2.Scan(&c.ID, &c.From, &c.To, &c.TravelMinutes, &c.Cost, &c.Cooled, &c.Active); err != nil {
			return nil, nil, err
		}
		conns = append(conns, &c)
	}
	return nodes, conns, nil
}

func loadLabAcceptance(ctx context.Context) (map[string]map[string]bool, error) {
	rows, err := pool.Query(ctx, `SELECT laboratory_id, sample_type_id, accepts FROM laboratory_acceptance`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	m := map[string]map[string]bool{}
	for rows.Next() {
		var lab, st string
		var acc bool
		if err := rows.Scan(&lab, &st, &acc); err != nil {
			return nil, err
		}
		if m[lab] == nil {
			m[lab] = map[string]bool{}
		}
		m[lab][st] = acc
	}
	return m, nil
}

func loadCapacity(ctx context.Context) (map[string]map[string]int, error) {
	// returns resource_id -> {"regular_config","cooled_config","regular_reserved","cooled_reserved"}
	rows, err := pool.Query(ctx, `SELECT resource_id, capacity_units, cooled_capacity_units FROM capacity_pools`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	m := map[string]map[string]int{}
	for rows.Next() {
		var rid string
		var reg, cooled int
		if err := rows.Scan(&rid, &reg, &cooled); err != nil {
			return nil, err
		}
		m[rid] = map[string]int{"reg_config": reg, "cooled_config": cooled, "reg_reserved": 0, "cooled_reserved": 0}
	}
	rows2, err := pool.Query(ctx, `SELECT resource_id, units, cooled FROM capacity_reservations`)
	if err != nil {
		return m, nil
	}
	defer rows2.Close()
	for rows2.Next() {
		var rid string
		var units int
		var cooled bool
		if err := rows2.Scan(&rid, &units, &cooled); err != nil {
			continue
		}
		if m[rid] == nil {
			m[rid] = map[string]int{"reg_config": 0, "cooled_config": 0, "reg_reserved": 0, "cooled_reserved": 0}
		}
		if cooled {
			m[rid]["cooled_reserved"] += units
		} else {
			m[rid]["reg_reserved"] += units
		}
	}
	return m, nil
}

func availableCapacity(cap map[string]int, cooled bool) int {
	if cap == nil {
		return 0
	}
	if cooled {
		return cap["cooled_config"] - cap["cooled_reserved"]
	}
	return cap["reg_config"] - cap["reg_reserved"]
}

func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLon := (lon2 - lon1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

type servResult struct {
	Serviceable           bool
	Reason                string
	TargetLaboratoryID    string
	EstimatedArrivalAt    time.Time
	ServiceabilityVersion int
}

func servingCollectionNodes(nodes map[string]*locationNode, lat, lng float64) []*locationNode {
	var out []*locationNode
	for _, n := range nodes {
		if !n.Active || !n.CollectionPoint {
			continue
		}
		d := haversineKm(lat, lng, n.Lat, n.Lng)
		maxReach := 5.0
		if n.CoverageKm > 0 && n.CoverageKm < 5.0 {
			maxReach = n.CoverageKm
		}
		if d <= maxReach {
			out = append(out, n)
		}
	}
	return out
}

type routePath struct {
	Nodes     []*locationNode
	Edges     []*connectionEdge
	TotalTime int // minutes
	TotalCost float64
}

func findRoute(ctx context.Context, nodes map[string]*locationNode, edges []*connectionEdge, accepts map[string]map[string]bool, caps map[string]map[string]int, sampleTypeID string, requiresCooled bool, startNode string, deadline time.Time) (*routePath, string) {
	// BFS over active edges; minimize total time; check lab acceptance + cooled + capacity.
	type state struct {
		node string
		path *routePath
	}
	// adjacency
	adj := map[string][]*connectionEdge{}
	for _, e := range edges {
		if e.Active && nodes[e.From].Active && nodes[e.To].Active {
			adj[e.From] = append(adj[e.From], e)
		}
	}
	best := map[string]int{} // node -> best time
	best[startNode] = 0
	queue := []state{{node: startNode, path: &routePath{Nodes: []*locationNode{nodes[startNode]}}}}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		// check if current node is accepting lab
		if nodes[cur.node].Laboratory && accepts[cur.node] != nil && accepts[cur.node][sampleTypeID] {
			arrival := now().Add(time.Duration(cur.path.TotalTime) * time.Minute)
			_ = arrival
			_ = deadline
			return cur.path, ""
		}
		for _, e := range adj[cur.node] {
			if requiresCooled && !e.Cooled {
				continue
			}
			// capacity check on connection
			if availableCapacity(caps[e.ID], requiresCooled) < 1 {
				continue
			}
			newTime := cur.path.TotalTime + e.TravelMinutes
			// add handling time at the destination node
			newTime += nodes[e.To].HandlingMinutes
			if bt, ok := best[e.To]; ok && bt <= newTime {
				continue
			}
			best[e.To] = newTime
			np := &routePath{
				Nodes:     append(append([]*locationNode{}, cur.path.Nodes...), nodes[e.To]),
				Edges:     append(append([]*connectionEdge{}, cur.path.Edges...), e),
				TotalTime: newTime,
				TotalCost: cur.path.TotalCost + e.Cost,
			}
			queue = append(queue, state{node: e.To, path: np})
		}
	}
	return nil, "no_route"
}

func checkServiceabilityLogic(ctx context.Context, originLat, originLng float64, originType string, originNodeID string, sampleTypeID string, requiresCooled bool, deadline time.Time) servResult {
	version := latestServVersion(ctx)
	res := servResult{ServiceabilityVersion: version}
	nodes, edges, err := loadNetwork(ctx)
	if err != nil {
		res.Reason = "no_route"
		return res
	}
	accepts, _ := loadLabAcceptance(ctx)
	caps, _ := loadCapacity(ctx)

	var candidates []*locationNode
	if originType == "node" && originNodeID != "" {
		n := nodes[originNodeID]
		if n == nil || !n.Active || !n.CollectionPoint {
			res.Reason = "outside_service_coverage"
			return res
		}
		candidates = []*locationNode{n}
	} else {
		candidates = servingCollectionNodes(nodes, originLat, originLng)
	}
	if len(candidates) == 0 {
		res.Reason = "outside_service_coverage"
		return res
	}

	// check accepting lab exists
	labExists := false
	for _, n := range nodes {
		if n.Laboratory && n.Active && accepts[n.ID] != nil && accepts[n.ID][sampleTypeID] {
			labExists = true
			break
		}
	}
	if !labExists {
		res.Reason = "no_accepting_laboratory"
		return res
	}

	var bestPath *routePath
	var failReason string
	for _, start := range candidates {
		p, reason := findRoute(ctx, nodes, edges, accepts, caps, sampleTypeID, requiresCooled, start.ID, deadline)
		if p != nil {
			if bestPath == nil || p.TotalTime < bestPath.TotalTime {
				bestPath = p
			}
		} else if reason != "" {
			failReason = reason
		}
	}
	if bestPath == nil {
		if failReason == "" {
			failReason = "no_route"
		}
		// distinguish capacity vs route vs handling
		// check capacity availability generally
		if !hasAnyCapacity(ctx, requiresCooled) {
			res.Reason = "insufficient_capacity"
			return res
		}
		if requiresCooled && !hasCooledRoute(edges) {
			res.Reason = "handling_rules_unsatisfiable"
			return res
		}
		res.Reason = failReason
		return res
	}
	arrival := now().Add(time.Duration(bestPath.TotalTime) * time.Minute)
	if !deadline.IsZero() && arrival.After(deadline) {
		res.Reason = "deadline_unreachable"
		return res
	}
	// target lab = last node
	targetLab := bestPath.Nodes[len(bestPath.Nodes)-1].ID
	res.Serviceable = true
	res.Reason = "serviceable"
	res.TargetLaboratoryID = targetLab
	res.EstimatedArrivalAt = arrival
	return res
}

func hasAnyCapacity(ctx context.Context, cooled bool) bool {
	caps, _ := loadCapacity(ctx)
	for _, c := range caps {
		if availableCapacity(c, cooled) >= 1 {
			return true
		}
	}
	return false
}

func hasCooledRoute(edges []*connectionEdge) bool {
	for _, e := range edges {
		if e.Active && e.Cooled {
			return true
		}
	}
	return false
}

func latestServVersion(ctx context.Context) int {
	var v int
	_ = pool.QueryRow(ctx, `SELECT version FROM serviceability_versions WHERE status='complete' ORDER BY version DESC LIMIT 1`).Scan(&v)
	if v == 0 {
		v = 1
	}
	return v
}

func recomputeServiceability(ctx context.Context) error {
	nodes, _, err := loadNetwork(ctx)
	if err != nil {
		return err
	}
	regions := []map[string]interface{}{}
	count := 0
	for _, n := range nodes {
		if n.Active && n.CollectionPoint {
			count++
			regions = append(regions, map[string]interface{}{
				"locationId":  n.ID,
				"name":         n.Name,
				"latitude":     n.Lat,
				"longitude":    n.Lng,
				"coverageKm":   n.CoverageKm,
			})
		}
	}
	regionsJSON, _ := json.Marshal(regions)
	rev := int(atomic.LoadInt64(&netRevision))
	_, err = pool.Exec(ctx, `INSERT INTO serviceability_versions (version, status, network_revision, computed_at, regions, active_collection_point_count)
		VALUES ((SELECT COALESCE(MAX(version),0)+1 FROM serviceability_versions), 'complete', $1, now(), $2::jsonb, $3)`,
		rev, string(regionsJSON), count)
	if err != nil {
		return err
	}
	return nil
}

func handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		errResp(w, http.StatusMethodNotAllowed, "method_not_allowed", "GET required")
		return
	}
	var version, rev, count int
	var status, computedAt string
	var regionsJSON []byte
	err := pool.QueryRow(r.Context(), `SELECT version, status, network_revision, computed_at::text, regions, active_collection_point_count FROM serviceability_versions WHERE status='complete' ORDER BY version DESC LIMIT 1`).
		Scan(&version, &status, &rev, &computedAt, &regionsJSON, &count)
	if err != nil {
		// compute one synchronously
		_ = recomputeServiceability(r.Context())
		err = pool.QueryRow(r.Context(), `SELECT version, status, network_revision, computed_at::text, regions, active_collection_point_count FROM serviceability_versions WHERE status='complete' ORDER BY version DESC LIMIT 1`).
			Scan(&version, &status, &rev, &computedAt, &regionsJSON, &count)
		if err != nil {
			errResp(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}
	}
	var regions []interface{}
	_ = json.Unmarshal(regionsJSON, &regions)
	if regions == nil {
		regions = []interface{}{}
	}
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{
		"version":                     version,
		"status":                      status,
		"computedAt":                  computedAt,
		"networkRevision":             rev,
		"regions":                     regions,
		"activeCollectionPointCount":  count,
	}})
}","path":"/workspace/backend/serviceability.go"}

