	return map[string]interface{}{"latitude": lat, "longitude": lng}
}

// buildTimeline returns audit entries for an entity, ordered oldest first.
func buildTimeline(ctx context.Context, entityType, entityID string) []map[string]interface{} {
	rows, err := pool.Query(ctx,
		`SELECT audit_id, COALESCE(actor_id::text,''), actor_role, action, entity_type, entity_id, success, occurred_at::text, details
		 FROM audit_log WHERE entity_type=$1 AND entity_id=$2 ORDER BY occurred_at ASC, audit_id ASC`, entityType, entityID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var auditID, actorID, actorRole, action, etype, eID, occurred string
		var success bool
		var details []byte
		if err := rows.Scan(&auditID, &actorID, &actorRole, &action, &etype, &eID, &success, &occurred, &details); err != nil {
			continue
		}
		var det interface{}
		if len(details) > 0 {
			det = jsonBytes(details)
		} else {
			det = map[string]interface{}{}
		}
		out = append(out, map[string]interface{}{
			"eventId":     auditID,
			"action":      action,
			"actorId":     actorID,
			"role":        actorRole,
			"entityType":  etype,
			"entityId":    eID,
			"success":     success,
			"occurredAt":  occurred,
			"details":     det,
		})
	}
	return out
}

func jsonBytes(b []byte) interface{} {
	var v interface{}
	_ = jsonUnmarshal(b, &v)
	return v
}

// buildCapacity returns the configured/reserved/available capacity object for a resource.
func buildCapacity(ctx context.Context, resourceID string) map[string]interface{} {
	var reg, cooled int
	_ = pool.QueryRow(ctx, `SELECT capacity_units, cooled_capacity_units FROM capacity_pools WHERE resource_id=$1`, resourceID).Scan(&reg, &cooled)
	var regRes, cooledRes int
	_ = pool.QueryRow(ctx, `SELECT COALESCE(SUM(units) FILTER (WHERE cooled=false),0), COALESCE(SUM(units) FILTER (WHERE cooled=true),0) FROM capacity_reservations WHERE resource_id=$1`, resourceID).Scan(&regRes, &cooledRes)
	return map[string]interface{}{
		"capacityUnits":        reg,
		"reservedUnits":        regRes,
		"availableUnits":       reg - regRes,
		"cooledCapacityUnits":  cooled,
		"cooledReservedUnits":  cooledRes,
		"cooledAvailableUnits": cooled - cooledRes,
	}
}

// buildJourneyPlan constructs the JourneyPlan response object for a journey.
func buildJourneyPlan(ctx context.Context, journeyID string) map[string]interface{} {
	var parentID, targetLab *string
	var planVersion int
	var routeMode, status string
	var estDelivery *string
	var totalCost float64
	var sampleID *string
	err := pool.QueryRow(ctx,
		`SELECT parent_journey_id, plan_version, route_mode, status, estimated_delivery_at::text, COALESCE(total_cost_units,0), target_laboratory_id, sample_id FROM journeys WHERE journey_id=$1`, journeyID).
		Scan(&parentID, &planVersion, &routeMode, &status, &estDelivery, &totalCost, &targetLab, &sampleID)
	if err != nil {
		return nil
	}

	// sampleIds: primary sample plus any linked via reservations
	sampleIDs := []string{}
	if sampleID != nil && *sampleID != "" {
		sampleIDs = append(sampleIDs, *sampleID)
	}
	rows, _ := pool.Query(ctx, `SELECT DISTINCT COALESCE(sample_id::text,'') FROM assignments WHERE journey_id=$1 AND sample_id IS NOT NULL`, journeyID)
	if rows != nil {
		for rows.Next() {
			var sid string
			_ = rows.Scan(&sid)
			if sid != "" && !contains(sampleIDs, sid) {
				sampleIDs = append(sampleIDs, sid)
			}
		}
		rows.Close()
	}

	// ordered stops
	stops := []map[string]interface{}{}
	srows, _ := pool.Query(ctx, `SELECT stop_id, location_id, stop_type, sequence, estimated_at::text, dwell_minutes, completed_at::text FROM journey_stops WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	if srows != nil {
		for srows.Next() {
			var stopID, locID, stopType, est string
			var seq, dwell int
			var completed *string
			_ = srows.Scan(&stopID, &locID, &stopType, &seq, &est, &dwell, &completed)
			var lat, lng float64
			_ = pool.QueryRow(ctx, `SELECT latitude, longitude FROM locations WHERE location_id=$1`, locID).Scan(&lat, &lng)
			st := map[string]interface{}{
				"stopId":       stopID,
				"locationId":   locID,
				"stopType":     stopType,
				"sequence":    seq,
				"estimatedAt": est,
				"dwellMinutes": dwell,
				"coordinate":  coordObj(lat, lng),
			}
			if completed != nil {
				st["completedAt"] = *completed
			}
			stops = append(stops, st)
		}
		srows.Close()
	}

	// legs (assignments)
	legs := []map[string]interface{}{}
	var assignedWorkerIDs []string
	var collIDs, nodeIDs, labIDs []string
	var firstTrans, midTrans, finalTrans string
	arows, _ := pool.Query(ctx, `SELECT assignment_id, sample_id, kind, sequence, status, from_location_id, to_location_id, worker_id FROM assignments WHERE journey_id=$1 ORDER BY sequence ASC, kind ASC`, journeyID)
	if arows != nil {
		transIdx := 0
		for arows.Next() {
			var aid, kind, astatus *string
			var seq int
			var sid, fromLoc, toLoc, workerID *string
			_ = arows.Scan(&aid, &sid, &kind, &seq, &astatus, &fromLoc, &toLoc, &workerID)
			id := ""
			if aid != nil {
				id = *aid
			}
			sampleIdStr := ""
			if sid != nil {
				sampleIdStr = *sid
			}
			k := ""
			if kind != nil {
				k = *kind
			}
			st := ""
			if astatus != nil {
				st = *astatus
			}
			leg := map[string]interface{}{
				"assignmentId": id,
				"sequence":    seq,
				"status":      st,
				"sampleId":    sampleIdStr,
			}
			if fromLoc != nil {
				leg["fromLocationId"] = *fromLoc
			}
			if toLoc != nil {
				leg["toLocationId"] = *toLoc
			}
			if workerID != nil {
				leg["workerId"] = *workerID
				if !contains(assignedWorkerIDs, *workerID) {
					assignedWorkerIDs = append(assignedWorkerIDs, *workerID)
				}
			}
			switch k {
			case "collection":
				collIDs = append(collIDs, id)
			case "node":
				nodeIDs = append(nodeIDs, id)
			case "laboratory":
				labIDs = append(labIDs, id)
			case "transport":
				transIdx++
				switch transIdx {
				case 1:
					firstTrans = id
				case 2:
					midTrans = id
				default:
					finalTrans = id
				}
			}
			legs = append(legs, leg)
		}
		arows.Close()
	}

	// capacity
	var capacityUsed int
	_ = pool.QueryRow(ctx, `SELECT COALESCE(SUM(units),0) FROM capacity_reservations WHERE journey_id=$1`, journeyID).Scan(&capacityUsed)
	capacityAvailable := 0
	if r := pool.QueryRow(ctx, `SELECT COALESCE(SUM(capacity_units)+SUM(cooled_capacity_units),0) FROM capacity_pools WHERE resource_id IN (SELECT DISTINCT resource_id FROM capacity_reservations WHERE journey_id=$1)`, journeyID); r.Scan(&capacityAvailable) == nil {
	}

	plan := map[string]interface{}{
		"journeyId":          journeyID,
		"planVersion":        planVersion,
		"routeMode":          routeMode,
		"status":             status,
		"sampleIds":           sampleIDs,
		"orderedStops":       stops,
		"legs":               legs,
		"assignedWorkerIds":  assignedWorkerIDs,
		"totalCostUnits":     totalCost,
		"capacityUsed":       capacityUsed,
		"capacityAvailable":  capacityAvailable,
		"valid":              status != "cancelled" && status != "expired",
	}
	if parentID != nil {
		plan["parentJourneyId"] = *parentID
	}
	if estDelivery != nil {
		plan["estimatedDeliveryAt"] = *estDelivery
	}
	if targetLab != nil {
		plan["targetLaboratoryId"] = *targetLab
	}
	if len(collIDs) > 0 {
		plan["collectionAssignmentId"] = collIDs[0]
		plan["collectionAssignmentIds"] = collIDs
	}
	if len(nodeIDs) > 0 {
		plan["nodeAssignmentIds"] = nodeIDs
	}
	if len(labIDs) > 0 {
		plan["laboratoryAssignmentIds"] = labIDs
	}
	if firstTrans != "" {
		plan["firstTransportAssignmentId"] = firstTrans
	}
	if midTrans != "" {
		plan["middleTransportAssignmentId"] = midTrans
	}
	if finalTrans != "" {
		plan["finalTransportAssignmentId"] = finalTrans
	}
	return plan
}"}

