func handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	ru := current(r)
	if ru.ActiveRole == "" {
		errResp(w, http.StatusConflict, "role_not_selected", "select a role first")
		return
	}
	var body struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	_ = parseJSONBody(r, &body)
	role := body.Role
	if role == "" {
		role = ru.ActiveRole
	}
	if !contains(ru.Roles, role) {
		errResp(w, http.StatusForbidden, "forbidden", "role not held")
		return
	}

	pending := []map[string]interface{}{}
	inProgress := []map[string]interface{}{}
	completed := []map[string]interface{}{}

	switch role {
	case "requester":
		rows, _ := pool.Query(r.Context(), `SELECT sample_id, request_id, status, serviceable, requested_at::text, delivery_deadline::text FROM requests WHERE requester_id=$1 ORDER BY created_at DESC`, ru.UserID)
		if rows != nil {
			for rows.Next() {
				var sid, rid, status string
				var serviceable bool
				var reqAt, deadline string
				_ = rows.Scan(&sid, &rid, &status, &serviceable, &reqAt, &deadline)
				item := map[string]interface{}{
					"kind":            "sample",
					"sampleId":        sid,
					"requestId":       rid,
					"status":          status,
					"serviceability":  boolStr(serviceable),
					"requestedAt":     reqAt,
					"deliveryDeadline": deadline,
					"history":         buildTimeline(r.Context(), "sample", sid),
					"locationStale":    true,
				}
				classifyItem(status, item, &pending, &inProgress, &completed)
			}
			rows.Close()
		}
	case "collection_professional":
		rows, _ := pool.Query(r.Context(), `SELECT a.assignment_id, a.sample_id, a.status, a.journey_id, a.offer_expires_at::text FROM assignments a WHERE a.offered_worker_id=$1 OR a.worker_id=$1`, ru.UserID)
		if rows != nil {
			for rows.Next() {
				var aid, sid, status string
				var jid *string
				var exp *string
				_ = rows.Scan(&aid, &sid, &status, &jid, &exp)
				item := map[string]interface{}{
					"kind":          "collection",
					"assignmentId":  aid,
					"sampleId":      sid,
					"status":        status,
					"history":       buildTimeline(r.Context(), "assignment", aid),
				}
				if jid != nil {
					item["journeyId"] = *jid
				}
				if exp != nil {
					item["offerExpiresAt"] = *exp
				}
				classifyItem(status, item, &pending, &inProgress, &completed)
			}
			rows.Close()
		}
	case "delivery_partner":
		rows, _ := pool.Query(r.Context(), `SELECT a.assignment_id, a.sample_id, a.status, a.journey_id, a.from_location_id, a.to_location_id, a.sequence FROM assignments a WHERE a.kind='transport' AND (a.offered_worker_id=$1 OR a.worker_id=$1)`, ru.UserID)
		if rows != nil {
			for rows.Next() {
