func handleEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		errResp(w, http.StatusMethodNotAllowed, "method_not_allowed", "GET required")
		return
	}
	// polling fallback: return recent events
	var cursor int64
	rows, err := pool.Query(r.Context(), `SELECT event_id, type, entity_type, entity_id, payload, created_at::text FROM realtime_events ORDER BY event_id DESC LIMIT 100`)
	events := []map[string]interface{}{}
	if err == nil {
		for rows.Next() {
			var id int64
			var etype, entityType, entityID, createdAt string
			var payload []byte
			_ = rows.Scan(&id, &etype, &entityType, &entityID, &payload, &createdAt)
			events = append(events, map[string]interface{}{
				"eventId":     id,
				"type":        etype,
				"entityType":  entityType,
				"entityId":    entityID,
				"payload":     jsonBytes(payload),
				"createdAt":   createdAt,
			})
			if cursor == 0 {
				cursor = id
			}
		}
		rows.Close()
	}
	jsonResp(w, http.StatusOK, map[string]interface{}{"data": map[string]interface{}{
		"events":  events,
		"cursor":  cursor,
	}})
}","path":"/workspace/backend/ops_dispatch.go"}

