}","new_str":"// migrateUsingOpenPool applies schema, seed and serviceability using the
// already-open global pool. It does NOT close the pool, so it is safe to use
// from serve mode where the pool must stay open for the server lifetime.
func migrateUsingOpenPool(ctx context.Context, fullReset bool) error {
	if fullReset {
		if _, err := pool.Exec(ctx, resetDropSQL); err != nil {
			return fmt.Errorf("drop: %w", err)
		}
	}
	if _, err := pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("schema: %w", err)
	}
	if err := seedDefaults(ctx, fullReset); err != nil {
		return fmt.Errorf("seed: %w", err)
	}
	if err := recomputeServiceability(ctx); err != nil {
		return fmt.Errorf("serviceability: %w", err)
	}
	return nil
}

func runMigrate(ctx context.Context) error {
	if err := openDB(ctx); err != nil {
		return err
	}
	defer closeDB()
	return migrateUsingOpenPool(ctx, false)
}

func runReset(ctx context.Context) error {
	if err := openDB(ctx); err != nil {
		return err
	}
	defer closeDB()
	return migrateUsingOpenPool(ctx, true)
}"}

